/-- Initialize registers from the supplied rational arguments, and all others to zero. -/
def RationalProgram.initial (xs : List ℚ) : RationalState :=
  (0, fun i => xs[i]?.getD 0, false)

/-- The alternating arctangent polynomial. -/
def arctanPolynomial (N : ℕ) (v : ℚ) : ℚ :=
  ∑ j ∈ Finset.range N, (-1 : ℚ) ^ j * v ^ (2 * j + 1) / (2 * j + 1 : ℕ)

/-- Arm risks, pinned to the conditional table. -/
def armRisk (P : ObservedLaw) (a : Bool) (x : Covariate) : ℝ :=
  P.cells a true x / (P.cells a false x + P.cells a true x) -- @realizes \mu(arm conditional risk)

/-- Binary law at a success probability. -/
def bernoulliLaw (p : ℝ) : Measure Bool :=
  ENNReal.ofReal (1-p) • Measure.dirac false + ENNReal.ofReal p • Measure.dirac true

/-- Domain-checked division. -/
def boxDiv (I J : RatInterval) : Option RatInterval :=
  if h : J.hi < 0 ∨ 0 < J.lo then some (I.div J h) else none

/-- [Exact interval intersection; an empty intersection is reported. -/
def boxIntersection (I J : RatInterval) : Option RatInterval :=
  if h : max I.lo J.lo ≤ min I.hi J.hi then some ⟨max I.lo J.lo, min I.hi J.hi, h⟩ else none

