/-- Cosine basis with the constant frequency separated. -/
def cosineBasis (j : ℕ) (x : Covariate) : ℝ :=
  if j = 0 then 1 else Real.sqrt 2 * Real.cos (Real.pi * j * (x : ℝ))

/-- Rank-k cosine projection. -/
def cosineProjection (k : ℕ) (f : Covariate → ℝ) (x : Covariate) : ℝ :=
  ∑ j ∈ Finset.range k, uniformInner f (cosineBasis j) * cosineBasis j x

/-- Binary-table covariance branch with the prescribed positive square root. -/
def covarianceBranch (t ξ υ : ℝ) : ℝ :=
  let d := Real.exp t - 1
  let v := ξ*(1-ξ)*υ*(1-υ)
  let L := 1+d*(ξ*(1-υ)+(1-ξ)*υ)
  2*d*v/(L+Real.sqrt (L^2-4*d^2*v)) -- @realizes \mathfrak c(binary-table covariance branch) @realizes \xi(first scalar margin) @realizes \upsilon(second scalar margin)

