/-- Integrated off-diagonal product. -/
def denominatorCoordinate (P : ObservedLaw) : ℝ :=
  ∫ x, cellProbability P true false x * cellProbability P false true x ∂uniformLaw -- @realizes S(off-diagonal product integral)

/-- Explicit diagnostic profile. -/
def diagnosticEnvelope (n : ℕ) (α β r : ℝ) : ℝ :=
  (n : ℝ) ^ (-exponentA α β) + r * (n : ℝ) ^ (-exponentB β) -- @realizes d_n(explicit power profile) @realizes n(sample size; positivity in statements)

/-- The displayed finite expression tree, retaining the rank-step integers. -/
def endpointExpressions (n kC kS : ℕ) (o : Fin n → Record) : BoxExpr × BoxExpr :=
  let cs := coordinateExpressions n kC kS o
  let bC := BoxExpr.add (.mul (.constant 8) (.power kC (.sub (.constant 0) (.add (.input 0) (.input 1)))))
    (.sqrt (.constant (20 * (10/(n : ℚ)+4*kC/((n : ℚ)*((n : ℚ)-1))))))
  let bS := BoxExpr.add (.mul (.constant 25) (.power kS (.mul (.constant (-2)) (.input 1))))
    (.sqrt (.constant (20 * (10/(n : ℚ)+4*kS/((n : ℚ)*((n : ℚ)-1))))))
  let sm := BoxExpr.max (.constant (1/512)) (.min (.constant 1) (.sub cs.2 bS))
  let sp := BoxExpr.max (.constant (1/512)) (.min (.constant 1) (.add cs.2 bS))
  (.min (inversionExpression (.sub cs.1 bC) sm) (inversionExpression (.sub cs.1 bC) sp),
   .max (inversionExpression (.add cs.1 bC) sm) (inversionExpression (.add cs.1 bC) sp))

/-- Monotone endpoint extension of a scalar routine. -/
def endpointExtension (F : ℕ → ℚ → RatInterval) (q : ℕ) (I : RatInterval) : RatInterval :=
  rationalBox (F q I.lo).lo (F q I.hi).hi

/-- Endpoint signs are extended by zero-index fallback only for k=0. -/
def endpointSign (k : ℕ) (σ : Fin (k + 1) → Bool) (j : ℕ) : ℝ :=
  signValue (σ ⟨min j k, Nat.lt_succ_of_le (min_le_right _ _)⟩)

