/-- [The closed effect, signed amplitude, and centering box; position is unrestricted. -/
-- @node: fairEquationParameterRegion
def fairEquationParameterRegion : Set (Fin 4 → ℝ) :=
  {v | v 0 ∈ Set.Icc (0 : ℝ) (1/4) ∧ |v 1| ≤ 1/100 ∧
    v 2 ∈ Set.Icc (3/10 : ℝ) (1/2)}

/-- Construct a fair random law from its explicit cells. -/
def fairLaw (k : ℕ) (σ : Fin (k + 1) → Bool) (t δ : ℝ) : ObservedLaw :=
  totalCellLaw (fairCells true k σ t δ)

/-- Fair original-record mixture. -/
def fairMixture (n k : ℕ) (t δ : ℝ) : Measure (Fin n → Record) :=
  finiteSignMixture n k (fun σ => fairLaw k σ t δ)

/-- Numerator of the normalized fair equation. -/
def fairNumerator (t δ ξ u : ℝ) : ℝ :=
  signAverage (fun s => riskShift t (ξ+δ*localSignField u s))-riskShift (comparatorEffect t δ) ξ

/-- Closed fair-amplitude neighbourhood, including zero effect and zero amplitude. -/
def fairParameterRegion (ε : ℝ) : Set (Fin 3 → ℝ) :=
  {v | v 0 ∈ Set.Icc (0 : ℝ) (1/4) ∧ |v 1| ≤ ε ∧ v 2 ∈ Set.Icc (0 : ℝ) 1}

/-- Choose the local fair centering root; outside its neighbourhood use 2/5. -/
def fairRoot (t δ u : ℝ) : ℝ :=
  if h : ∃ p : ℝ, p ∈ Set.Ioo (3/10) (1/2) ∧ fairEquation t δ p u = 0 then Classical.choose h else 2/5

/-- [The compact box on which the fair Taylor equation is used. -/
-- @node: fairTaylorParameterRegion
def fairTaylorParameterRegion : Set (Fin 4 → ℝ) :=
  Set.pi Set.univ (fun i => if i = 0 then Set.Icc (0 : ℝ) (1 / 4)
    else if i = 1 then Set.Icc (-(1 / 100 : ℝ)) (1 / 100)
    else if i = 2 then Set.Icc (3 / 10 : ℝ) (1 / 2) else Set.Icc (0 : ℝ) 1)

