/-- One binary integer-square-root step. -/
def integerSqrtStep (N : ℕ) (lu : ℕ × ℕ) : ℕ × ℕ :=
  if lu.2 - lu.1 = 1 then lu else
    let a := (lu.1 + lu.2) / 2
    if a ^ 2 ≤ N then (a, lu.2) else (lu.1, a)

/-- Interval membership, respecting endpoint inclusion. -/
def intervalSet (B : EffectInterval) : Set ℝ :=
  {t | (B.val.1 < t ∨ (B.val.2.2.1 = true ∧ B.val.1 = t)) ∧
       (t < B.val.2.1 ∨ (B.val.2.2.2 = true ∧ t = B.val.2.1))}

/-- Joint odds inversion with the public effect clipping. -/
def inversion (c d : ℝ) : ℝ :=
  Real.log (clip (Real.exp (-1/2)) (Real.exp (1/2)) (1 + c / d))

/-- Projection kernel expression. -/
def kernelExpression (k i j : ℕ) : BoxExpr :=
  expressionSum ((List.range k).map fun l => .mul (basisExpression l i) (basisExpression l j))

/-- Infimum of worst-case length over globally honest procedures. -/
def lengthObjective (n : ℕ) (α β r : ℝ) : ℝ :=
  sInf {l | ∃ I : Procedure n, HonestProcedure n α β I ∧ l = worstLength n α β r I} -- @realizes J(minimax expected length)

/-- Two auxiliary signs at a within-cell coordinate. -/
def localSignField (u : ℝ) (s : Bool × Bool) : ℝ :=
  signValue s.1 * Real.cos (Real.pi*u/2) + signValue s.2 * Real.sin (Real.pi*u/2)

/-- Exact atanh logarithm polynomial, with the specified count. -/
def logPolynomial (q : ℕ) (z : ℚ) : ℚ :=
  let B := logRangeBound z
  let v := (z - 1) / (z + 1)
  2 * ∑ j ∈ Finset.range (B * (q + 3 + Nat.clog 2 (8 * B) + 2)),
    v ^ (2 * j + 1) / (2 * j + 1 : ℕ)

/-- Rational range bound for the logarithm. -/
def logRangeBound (z : ℚ) : ℕ :=
  max 2 (max (⌈z⌉ : ℤ).toNat (⌈1 / z⌉ : ℤ).toNat)

