/-- [The two endpoint indices on which a record depends. -/
-- @node: recordSignEndpoints
def recordSignEndpoints (k : ℕ) (x : Covariate) : Finset ℕ :=
  {cellIndex k x, cellIndex k x + 1}

/-- [Common dominating reference for exactly n records. -/
def sampleReference (n : ℕ) : Measure (Fin n → Record) :=
  Causalean.Stat.UStatistic.LocalizedVariance.iidLaw recordReference n

/-- Concrete sequence uses precisely the certified concrete engine and the floor policy. -/
def starInterval (n : ℕ) (α β : ℝ) : Procedure n :=
  upperInterval concreteEngine dyadicFloorPolicy fixed_budget_realization.1 n α β

/-- A four-cell table from margins and covariance. -/
def tableCell (e m c : ℝ) (a y : Bool) : ℝ :=
  if a then (if y then e*m+c else e*(1-m)-c)
  else (if y then (1-e)*m-c else (1-e)*(1-m)+c)

/-- Total cell-law constructor; on valid cells it is literally the given cell law. -/
def totalCellLaw (p : Bool → Bool → Covariate → ℝ) : ObservedLaw :=
  if h : ValidCells p then lawFromCells p h else lawFromCells (fun _ _ _ => 1/4) fairDefault_valid

/-- Uniform L2 norm, with extended semantics. -/
def uniformL2Norm (f : Covariate → ℝ) : ℝ≥0∞ :=
  (∫⁻ x, ENNReal.ofReal (f x ^ 2) ∂uniformLaw).rpow (1 / 2)

